BACKUP DATABASE SalesDB
TO DISK = 'C:\Backups\SalesDB_Full.bak'
WITH COMPRESSION, CHECKSUM, STATS = 10;

USE msdb;
GO
EXEC sp_add_job @job_name = N'Nightly Index Maintenance';

EXEC sp_add_jobstep
    @job_name = N'Nightly Index Maintenance',
    @step_name = N'Run Index Maintenance',
    @subsystem = N'TSQL',
    @command = N'EXEC dbo.usp_IndexMaintenance;',
    @database_name = N'SalesDB';

EXEC sp_add_schedule
    @schedule_name = N'Daily1AM',
    @freq_type = 4,            -- daily
    @freq_interval = 1,
    @active_start_time = 010000;

EXEC sp_attach_schedule
    @job_name = N'Nightly Index Maintenance',
    @schedule_name = N'Daily1AM';

EXEC sp_add_jobserver
    @job_name = N'Nightly Index Maintenance',
    @server_name = N'(local)';

-- Check fragmentation
SELECT i.name AS IndexName, ips.avg_fragmentation_in_percent
FROM sys.dm_db_index_physical_stats(DB_ID(), OBJECT_ID('Sales.Orders'), NULL, NULL, 'LIMITED') AS ips
JOIN sys.indexes AS i ON i.object_id = ips.object_id AND i.index_id = ips.index_id
WHERE ips.avg_fragmentation_in_percent > 10;

-- Moderate fragmentation (10-30%): reorganize
ALTER INDEX ALL ON Sales.Orders REORGANIZE;

-- Severe fragmentation (> 30%): rebuild
ALTER INDEX ALL ON Sales.Orders REBUILD;

SET STATISTICS XML ON;
GO
SELECT OrderID, OrderDate, CustomerID
FROM Sales.Orders
WHERE OrderDate >= '2026-01-01';
GO
SET STATISTICS XML OFF;
-- In SSMS, the Messages/Results pane shows a clickable XML plan link;
