-- Differential: changes since the last FULL backup (not since the last diff)
BACKUP DATABASE SalesDB
TO DISK = 'C:\Backups\SalesDB_Diff.bak'
WITH DIFFERENTIAL, COMPRESSION;

-- Transaction log: records since the last log backup
BACKUP LOG SalesDB
TO DISK = 'C:\Backups\SalesDB_Log.trn'
WITH COMPRESSION;

-- Example restore sequence
RESTORE DATABASE SalesDB FROM DISK = 'C:\Backups\SalesDB_Full.bak' WITH NORECOVERY;
RESTORE DATABASE SalesDB FROM DISK = 'C:\Backups\SalesDB_Diff.bak' WITH NORECOVERY;
RESTORE LOG SalesDB FROM DISK = 'C:\Backups\SalesDB_Log.trn' WITH RECOVERY;

-- WRONG: always returns zero rows, even when MiddleName IS NULL for many people
SELECT FirstName, MiddleName FROM Person.Person WHERE MiddleName = NULL;

-- CORRECT
SELECT FirstName, MiddleName FROM Person.Person WHERE MiddleName IS NULL;

-- Substituting a readable default instead of filtering
SELECT FirstName, ISNULL(MiddleName, '(none)') AS MiddleName FROM Person.Person;

